// This file is generated by AI.

import { describe, expect, it } from 'vitest';

import { NovelSession, type IEditorHost } from '../src/session';

class FakeHost implements IEditorHost {
  content = '';
  readOnly = false;
  selected: [number, number] | null = null;
  private contentCbs: Array<(t: string) => void> = [];
  private cursorCbs: Array<(l: number) => void> = [];
  private keyCbs: Array<(k: string) => boolean> = [];

  getContent(): string {
    return this.content;
  }
  setContent(text: string): void {
    this.content = text;
    this.contentCbs.forEach((cb) => cb(text));
  }
  setReadOnly(readOnly: boolean): void {
    this.readOnly = readOnly;
  }
  replaceLine(line: number, text: string): void {
    const lines = this.content.split('\n');
    lines[line] = text;
    this.content = lines.join('\n');
    this.contentCbs.forEach((cb) => cb(this.content));
  }
  selectLines(start: number, end: number): void {
    this.selected = [start, end];
  }
  setCursorLine(line: number): void {
    this.cursorCbs.forEach((cb) => cb(line));
  }
  onContentChange(cb: (t: string) => void): () => void {
    this.contentCbs.push(cb);
    return () => {};
  }
  onCursorLine(cb: (l: number) => void): () => void {
    this.cursorCbs.push(cb);
    return () => {};
  }
  onKey(cb: (k: string) => boolean): () => void {
    this.keyCbs.push(cb);
    return () => {};
  }
  focus(): void {}
  emitKey(key: string): boolean {
    return this.keyCbs.some((cb) => cb(key));
  }
  emitCursor(line: number): void {
    this.cursorCbs.forEach((cb) => cb(line));
  }
}

describe('NovelSession', () => {
  it('完整流程: 输入 → 处理 → 分配 → 导出', () => {
    const host = new FakeHost();
    const session = new NovelSession(host);

    expect(session.getState().step).toBe(1);
    expect(session.getState().canGoNext).toBe(false);

    // 第 1 步: 输入原文
    host.setContent('“你好。”\n今天天气不错。');
    expect(session.getState().canGoNext).toBe(true);
    session.next();

    expect(session.getState().step).toBe(2);
    expect(session.getState().text).toBe('; “你好。”\n%:你好。\n; 今天天气不错。\n:今天天气不错。');
    expect(host.readOnly).toBe(false);

    // 第 2 步 -> 第 3 步 (注释保留)
    session.next();
    expect(session.getState().step).toBe(3);
    expect(host.readOnly).toBe(true);
    expect(session.getState().unresolvedCount).toBe(1);
    expect(session.getState().text).toBe('; “你好。”\n%:你好。\n; 今天天气不错。\n:今天天气不错。');

    // 分配说话者
    session.addSpeaker();
    session.updateSpeaker('1', { name: '小明' });
    host.emitCursor(1); // 光标移到对话段 (第 1 行为注释)
    const handled = host.emitKey('1');
    expect(handled).toBe(true);
    expect(session.getState().unresolvedCount).toBe(0);
    expect(session.getState().text).toBe('; “你好。”\n1-小明:你好。\n; 今天天气不错。\n:今天天气不错。');

    // 第 3 步 -> 第 4 步 (无未分配, 直接导出; 注释被忽略)
    session.next();
    expect(session.getState().step).toBe(4);
    expect(session.getState().text).toBe('小明:你好。;\n:今天天气不错。;');
  });

  it('光标未选中时锁定到向下最近的对话段', () => {
    const host = new FakeHost();
    const session = new NovelSession(host);
    host.setContent('今天是晴天。\n“你好。”');
    session.next(); // 1 -> 2
    session.next(); // 2 -> 3
    session.addSpeaker();
    session.updateSpeaker('1', { name: '小明' });
    // 光标停在第一行 (旁白/注释区域, 未选中对话段)
    host.emitCursor(0);
    const handled = host.emitKey('1');
    expect(handled).toBe(true);
    expect(session.getState().unresolvedCount).toBe(0);
    expect(session.getState().text).toContain('1-小明:你好。');
  });

  it('未分配时确认按旁白处理', () => {
    const host = new FakeHost();
    const session = new NovelSession(host);
    host.setContent('“你好。”');
    session.next(); // 1 -> 2
    session.next(); // 2 -> 3
    session.next(); // 3 -> 有未分配, 触发确认
    expect(session.getState().pendingConfirm).toBe(true);
    expect(session.getState().step).toBe(3);

    session.resolveUnresolved(true);
    expect(session.getState().step).toBe(4);
    expect(session.getState().text).toBe(':你好。;');
  });

  it('返回上一步恢复状态', () => {
    const host = new FakeHost();
    const session = new NovelSession(host);
    host.setContent('“你好。”');
    session.next(); // 1 -> 2
    session.next(); // 2 -> 3
    session.back(); // 3 -> 2
    expect(session.getState().step).toBe(2);
    expect(host.readOnly).toBe(false);
    expect(session.getState().text).toBe('; “你好。”\n%:你好。');
  });

  it('第 2 步的差异基准是预处理后的文本', () => {
    const host = new FakeHost();
    const session = new NovelSession(host);
    expect(session.getState().stepBaseline).toBeNull();

    host.setContent('“你好。”\n今天天气不错。');
    session.next(); // 1 -> 2
    const baseline = '; “你好。”\n%:你好。\n; 今天天气不错。\n:今天天气不错。';
    expect(session.getState().stepBaseline).toBe(baseline);
    // 刚进来时没有改动 (基准就是编辑器里这份文本)
    expect(session.getState().text).toBe(baseline);

    // 第 2 步里手改文本不会改变基准 (基准是"本步开始时"的状态), 差异就是这次手改
    host.setContent('; “你好。”\n%:你好呀。\n; 今天天气不错。\n:今天天气不错。');
    expect(session.getState().stepBaseline).toBe(baseline);
    expect(session.getState().text).toBe('; “你好。”\n%:你好呀。\n; 今天天气不错。\n:今天天气不错。');
  });

  it('第 3 步的差异基准是进入时的文本', () => {
    const host = new FakeHost();
    const session = new NovelSession(host);
    host.setContent('“你好。”');
    session.next(); // 1 -> 2
    session.next(); // 2 -> 3
    const baseline = session.getState().stepBaseline;
    expect(baseline).toBe('; “你好。”\n%:你好。');
    expect(session.getState().text).toBe(baseline);

    // 分配说话者只改当前文本, 基准不动 (差异色块要显示的就是这次改动)
    session.addSpeaker();
    session.updateSpeaker('1', { name: '小明' });
    host.emitCursor(1);
    host.emitKey('1');
    expect(session.getState().text).toBe('; “你好。”\n1-小明:你好。');
    expect(session.getState().stepBaseline).toBe(baseline);
  });

  it('回到上一步改完再进来时, 基准按当时的文本重算', () => {
    const host = new FakeHost();
    const session = new NovelSession(host);
    host.setContent('“你好。”');
    session.next(); // 1 -> 2
    session.next(); // 2 -> 3
    session.back(); // 3 -> 2
    expect(session.getState().stepBaseline).toBe('; “你好。”\n%:你好。');

    host.setContent('; “你好。”\n%:你好。\n:补充一句。');
    session.next(); // 2 -> 3
    expect(session.getState().stepBaseline).toBe('; “你好。”\n%:你好。\n:补充一句。');
  });
});
